//! Four JPEG files, as hex, that no code here can write: the encoder in the `image` crate
//! writes one kind of JPEG. They were made once, by hand, with `cjpeg` of libjpeg-turbo 3.2.1
//! at quality 90, from a 16 by 16 picture whose pixel at `(x, y)` is red `(16x + 3y) mod 256`,
//! green `(14y + 9((xy) mod 7)) mod 256` and blue `(255 - 9x - 5y + 20((x xor y) and 3)) mod
//! 256`: with 2x2 chroma sampling, with none, progressive with 2x2 sampling, and in grey.
//! `vectors.rs` builds its JPEG vectors from them.

pub const BASELINE_420: &str = "";

pub const BASELINE_444: &str = "";

pub const PROGRESSIVE: &str = "";

pub const GREY: &str = "";
